type MetricsRepository interface {
	AddGauge(name string, value float64)
	AddCounter(name string, value int64)
	CheckGaugeType(name string) bool
	CheckCounterType(name string) bool
	GetTypeValue(name string) any
	AddBatch(data models.MetricsList) error
}

type FileStorage struct {
	*MemStorage
}

type DBStorage struct {
	*MemStorage
}

type MemStorage struct {
	Data      map[string]any
	StoreSync bool
	FilePath  string
	mu        sync.Mutex
	DB        *sql.DB
	ctx       context.Context
	WithDB    bool
}

var _ MetricsRepository = (*MemStorage)(nil)
var _ MetricsRepository = (*FileStorage)(nil)
var _ MetricsRepository = (*DBStorage)(nil)

func NewFileStorage(ctx context.Context, storeSync bool, filePath string, restore bool) *FileStorage {
	return &FileStorage{
		MemStorage: NewMemStorage(ctx, storeSync, filePath, restore, nil, false),
	}
}

func NewDBStorage(ctx context.Context, db *sql.DB) *DBStorage {
	return &DBStorage{
		MemStorage: NewMemStorage(ctx, false, "", false, db, true),
	}
}

