419: 		ON CONFLICT (name) DO UPDATE SET
420: 			m_type = 'counter',
421: 			delta = CASE WHEN metrics.m_type = 'counter' THEN metrics.delta + EXCLUDED.delta ELSE EXCLUDED.delta END,
422: 			value = 0
423: 	`)
424: 	if err != nil {
425: 		return err
426: 	}
427: 	defer stmtCounter.Close()
428: 
429: 	for _, metric := range data {
430: 		switch metric.MType {
431: 		case models.Gauge:
432: 			_, err = stmtGauge.ExecContext(txCtx, metric.ID, *metric.Value)
433: 		case models.Counter:
434: 			_, err = stmtCounter.ExecContext(txCtx, metric.ID, *metric.Delta)
435: 		}
436: 		if err != nil {
437: 			return err
438: 		}
439: 	}
